def build_full_catalog(live_adapter_ids: set[str] | None = None) -> list[SourceMetadata]:
    """Build the complete SourceMetadata list for all 118 Global + Brazil OSINT sources."""
    live_ids = live_adapter_ids or set()
    catalog: list[SourceMetadata] = []

    for src_id, name, url, category, desc, model, auth_type, accepts, produces in RAW_GLOBAL_100:
        trust = TrustLevel.OFFICIAL if src_id in {"rdap", "iana_rdap", "dns_doh", "cloudflare_doh"} else TrustLevel.HIGH
        catalog.append(
            SourceMetadata(
                id=src_id,
                name=name,
                provider=name.split()[0],
                category=category,
                url=url,
                description=f"[{model}] {desc}",
                trust_level=trust,
                tos_url=url,
                auth_type=auth_type,
                rate_limit_per_min=60 if auth_type == "none" else 30,
                cost_per_call=0.0,
                region="global",
                accepts=accepts,
                produces=produces,
                enabled=True,
                has_live_adapter=(src_id in live_ids),
            )
        )

    for src_id, name, url, category, desc, model, auth_type, accepts, produces in RAW_BRAZIL_SOURCES:
        trust = TrustLevel.OFFICIAL if model == "Oficial" else TrustLevel.HIGH
        catalog.append(
            SourceMetadata(
                id=src_id,
                name=name,
                provider=name.split()[0],
                category=category,
                url=url,
                description=f"[Brasil • {model}] {desc}",
                trust_level=trust,
                tos_url=url,
                auth_type=auth_type,
                rate_limit_per_min=30,
                cost_per_call=0.0,
                region="brasil",
                accepts=accepts,
                produces=produces,
                enabled=True,
                has_live_adapter=(src_id in live_ids),
            )
        )

    return catalog
